import React from 'react';
import { Layout, Menu } from 'antd';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import {
  DashboardOutlined,
  UserOutlined,
  CalendarOutlined,
  PieChartOutlined,
  NotificationOutlined,
  FormOutlined,
  TableOutlined,
  EnvironmentOutlined,
  ClockCircleOutlined,
  LineChartOutlined
} from '@ant-design/icons';

import './App.css';
import MainLayout from './layouts/MainLayout';
import AuthLayout from './layouts/AuthLayout';
import FormLogin from './components/form/FormLogin';
import FormSurvey from './components/form/FormSurvey';
import FormBasic from './components/form/FormBasic';
import Calendar from './components/calendar/Calendar';
import MiniCalendar from './components/calendar/MiniCalendar';
import Card from './components/card/Card';
import ProgressBar from './components/progress/ProgressBar';
import ProgressCircle from './components/progress/ProgressCircle';
import ProgressSteps from './components/progress/ProgressSteps';
import Notification from './components/notification/Notification';
import NotificationCenter from './components/notification/NotificationCenter';
import PieChart from './components/chart/PieChart';
import LineChart from './components/chart/LineChart';
import BarChart from './components/chart/BarChart';
import MapComponent from './components/map/MapComponent';
import Table from './components/table/Table';
import Timeline from './components/timeline/Timeline';
import Dashboard from './pages/Dashboard';

const { Header, Content, Sider } = Layout;

const App: React.FC = () => {
  return (
    <Router>
      <Layout style={{ minHeight: '100vh' }}>
        <Sider collapsible>
          <div className="logo" />
          <Menu theme="dark" defaultSelectedKeys={['1']} mode="inline">
            <Menu.Item key="1" icon={<DashboardOutlined />}>
              <Link to="/">Dashboard</Link>
            </Menu.Item>
            <Menu.Item key="2" icon={<UserOutlined />}>
              <Link to="/users">Users</Link>
            </Menu.Item>
            <Menu.Item key="3" icon={<CalendarOutlined />}>
              <Link to="/calendar">Calendar</Link>
            </Menu.Item>
            <Menu.Item key="4" icon={<PieChartOutlined />}>
              <Link to="/charts">Charts</Link>
            </Menu.Item>
            <Menu.Item key="5" icon={<NotificationOutlined />}>
              <Link to="/notifications">Notifications</Link>
            </Menu.Item>
            <Menu.Item key="6" icon={<FormOutlined />}>
              <Link to="/forms">Forms</Link>
            </Menu.Item>
            <Menu.Item key="7" icon={<TableOutlined />}>
              <Link to="/tables">Tables</Link>
            </Menu.Item>
            <Menu.Item key="8" icon={<EnvironmentOutlined />}>
              <Link to="/maps">Maps</Link>
            </Menu.Item>
            <Menu.Item key="9" icon={<ClockCircleOutlined />}>
              <Link to="/timeline">Timeline</Link>
            </Menu.Item>
            <Menu.Item key="10" icon={<LineChartOutlined />}>
              <Link to="/progress">Progress</Link>
            </Menu.Item>
          </Menu>
        </Sider>
        <Layout className="site-layout">
          <Header className="site-layout-background" style={{ padding: 0 }} />
          <Content style={{ margin: '0 16px' }}>
            <Routes>
              <Route path="/" element={<Dashboard />} />
              <Route path="/login" element={<AuthLayout><FormLogin /></AuthLayout>} />
              <Route path="/survey" element={<AuthLayout><FormSurvey /></AuthLayout>} />
              <Route path="/basic" element={<AuthLayout><FormBasic /></AuthLayout>} />
              <Route path="/calendar" element={<Calendar />} />
              <Route path="/minicalendar" element={<MiniCalendar />} />
              <Route path="/card" element={<Card />} />
              <Route path="/progressbar" element={<ProgressBar />} />
              <Route path="/progresscircle" element={<ProgressCircle />} />
              <Route path="/progresssteps" element={<ProgressSteps />} />
              <Route path="/notification" element={<Notification />} />
              <Route path="/notificationcenter" element={<NotificationCenter />} />
              <Route path="/piechart" element={<PieChart />} />
              <Route path="/linechart" element={<LineChart />} />
              <Route path="/barchart" element={<BarChart />} />
              <Route path="/map" element={<MapComponent />} />
              <Route path="/table" element={<Table />} />
              <Route path="/timeline" element={<Timeline />} />
            </Routes>
          </Content>
        </Layout>
      </Layout>
    </Router>
  );
};

export default App;

